mapper.select:
SELECT o.*, r.report_no, r.animal_type as report_animal_type, r.district as report_district, r.address as report_address, r.description as report_description, r.photos as report_photos, r.longitude, r.latitude, u.nickname as reporter_name, u.phone as reporter_phone, v.real_name as volunteer_name, v.phone as volunteer_phone, a.name as animal_name, a.breed as animal_breed, a.health_status as animal_status, h.name as hospital_name FROM rescue_order o LEFT JOIN stray_report r ON o.report_id = r.id LEFT JOIN user u ON r.user_id = u.id LEFT JOIN volunteer v ON o.volunteer_id = v.id LEFT JOIN animal a ON o.animal_id = a.id LEFT JOIN hospital h ON o.hospital_id = h.id WHERE o.deleted = 0
AND o.status = #{params.status}
AND o.district = #{params.district}
AND o.order_no LIKE CONCAT('%', #{params.orderNo}, '%')
AND o.create_time >= #{params.startTime}
AND o.create_time <= #{params.endTime}
ORDER BY o.create_time DESC
